style.css:
/* Aplicar fondo negro a todos los elementos */
* {
    background-color: #000000 !important;
    color: #00FF00 !important; /* Aseguramos que el texto sea verde */
    border-color: #00FF00 !important; /* También los bordes */
}

/* Excepciones para ciertos elementos donde el contenido debe ser visible */
img, video, canvas, iframe, embed, object, svg {
    background-color: transparent !important; /* Las imágenes y videos deben mostrar su contenido */
}

/* Para elementos con texto dentro que podrían tener su propio fondo */
*:not(html):not(body):not(img):not(video):not(canvas):not(iframe):not(embed):not(object):not(svg) * {
    background-color: transparent !important; /* Hacer transparentes los fondos anidados */
}

/* Estilos específicos para enlaces */
a {
    color: #00FF00 !important;
}

a:hover {
    color: #ADFF2F !important;
}

/* Para el texto seleccionado */
::selection {
    background-color: #00FF00 !important;
    color: #000000 !important;
}

/* Para placeholders de formularios */
::-webkit-input-placeholder { color: #808080 !important; }
:-ms-input-placeholder { color: #808080 !important; }
::placeholder { color: #808080 !important; }
